package dev.mcpmcp.forge;
import com.google.gson.*;import dev.mcpmcp.core.*;import dev.mcpmcp.api.*;import java.nio.file.*;import java.util.*;import java.util.jar.*;
public final class PluginManagerTest {
 static int sends()throws Exception{var f=PacketService.class.getDeclaredField("sends");f.setAccessible(true);return f.getInt(null);} static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 static JsonObject object(String s){return JsonParser.parseString(s.replace((char)39,(char)34)).getAsJsonObject();}
 static JsonObject action(){return object("{'name':'test.send','input_schema':{'type':'object','properties':{},'additionalProperties':false},'packet':{'packet_class':'dev.mcpmcp.forge.PluginManagerTest$Message','signature':['int'],'values':[1]},'verify':[{'kind':'inventory','item_id':'minecraft:stone','min_count':1}]}");}
 public static final class Message {static int constructed;public Message(int i){constructed++;}}
 public static final class Broken implements McpmcpPlugin {public String id(){return "broken";}public void register(PluginContext c){c.action("broken.partial",object("{'type':'object'}"),"packet","normal",a->new JsonObject());c.observer("broken",1,a->new JsonObject());throw new IllegalStateException("register failure");}}
 public static final class BadConstructor implements McpmcpPlugin {public BadConstructor(){throw new IllegalStateException("ctor failure");}public String id(){return "bad_ctor";}public void register(PluginContext c){}}
 public static final class Good implements McpmcpPlugin {static int registrations;public String id(){return "good";}public void register(PluginContext c){registrations++;c.action("good.action",object("{'type':'object'}"),"packet","normal",a->new JsonObject());c.observer("good.error",100,a->Jsons.error("not_in_world"));c.observer("good.fallback",100,a->Jsons.error("first_unavailable"));c.observer("good.fallback",1,a->Jsons.obj("source","fallback"));c.observer("good.linkage",100,a->{throw new NoClassDefFoundError("optional.Dependency");});}}
 public static void main(String[] args)throws Exception {
 Path root=Files.createTempDirectory(Path.of(args[0]),"plugins-"),dir=Files.createDirectories(root.resolve("test"));JsonObject manifest=object("{'api':1,'id':'test','mod_id':'minecraft'}");JsonArray actions=new JsonArray();actions.add(action());manifest.add("actions",actions);Path file=dir.resolve("plugin.json");Files.writeString(file,manifest.toString());PluginManager manager=new PluginManager(root);
 check(!manager.reload().has("error"),"valid reload");check(Message.constructed==0,"preflight must not construct");String revision=manager.revision();
 JsonObject invalid=manifest.deepCopy();invalid.getAsJsonArray("actions").get(0).getAsJsonObject().remove("packet");Files.writeString(file,invalid.toString());check(manager.reload().has("error")&&manager.revision().equals(revision)&&manager.hasAction("test.send"),"invalid reload retains revision/actions");Files.writeString(file,manifest.toString());
 Files.writeString(dir.resolve("actions.json"),"[".repeat(18)+"0"+"]".repeat(18));check(manager.reload().has("error"),"external budget");Files.delete(dir.resolve("actions.json"));
 Jobs.Step s=manager.create("test.send",new JsonObject());check(Jsons.bool(s.tick(),"pending",false),"verify pending");check(Jsons.bool(s.tick(),"pending",false),"verify repeated pending");check(Jsons.bool(s.tick(),"observed_success",false)&&sends()==1,"one send then observed verify");
 check(manager.create("test.send",Jsons.obj("plugin_revision","old")).tick().has("error")&&sends()==1,"revision before send");
 Path outside=root.resolveSibling("outside-plugin.json");Files.writeString(outside,manifest.toString());try{Files.delete(file);Files.createSymbolicLink(file,outside);check(manager.reload().has("error"),"manifest symlink denied");Files.delete(file);}catch(java.io.IOException|UnsupportedOperationException e){System.out.println("symlink fixture unavailable: "+e);}Files.writeString(file,manifest.toString());
 try(JarOutputStream jar=new JarOutputStream(Files.newOutputStream(dir.resolve("adapter.jar")))){jar.putNextEntry(new JarEntry("META-INF/services/dev.mcpmcp.api.McpmcpPlugin"));jar.write((String.join(String.valueOf((char)10),"missing.Provider",BadConstructor.class.getName(),Broken.class.getName(),Good.class.getName())+(char)10).getBytes(java.nio.charset.StandardCharsets.UTF_8));jar.closeEntry();}
 check(!manager.reload().has("error"),"restore reload");manager.setContext(new PluginContext(){public void action(String n,JsonObject s,String t,String p,Handler h){}public void observer(String k,int p,Handler h){}public JsonObject execute(String n,JsonObject a){return new JsonObject();}public JsonObject observe(String k,JsonObject a){return new JsonObject();}});manager.loadTrustedJavaOnce();manager.loadTrustedJavaOnce();
 check(manager.hasAction("good.action")&&Good.registrations==1,"provider continues and cold loads once");check(!manager.hasAction("broken.partial")&&manager.observe("broken",new JsonObject()).isEmpty(),"failed registration rolls back actions and observers");check(manager.status().toString().contains("java_error"),"service failures reported");
 check(manager.observe("good.error",new JsonObject()).orElseThrow().get("error").getAsString().equals("not_in_world"),"business error stays visible");
check(manager.observe("good.fallback",new JsonObject()).orElseThrow().get("source").getAsString().equals("fallback"),"lower priority observer may succeed after earlier error");
check(manager.observe("good.linkage",new JsonObject()).orElseThrow().get("error").getAsString().equals("plugin_observer_failed"),"optional linkage failure stays visible");
check(manager.observe("not_registered",new JsonObject()).isEmpty(),"unknown kind retains native fallback");
var loaderField=PluginManager.class.getDeclaredField("loaders");loaderField.setAccessible(true);for(Object l:(java.util.List<?>)loaderField.get(manager))((java.net.URLClassLoader)l).close();Files.delete(dir.resolve("adapter.jar"));manager.reload();JsonObject javaState=manager.status().getAsJsonArray("plugins").get(0).getAsJsonObject();check(javaState.get("java_loaded").getAsBoolean()&&javaState.get("java_restart_required").getAsBoolean(),"removed cold jar still needs restart");
 JsonObject incompatible=manifest.deepCopy();incompatible.addProperty("target_version","0.0-incompatible");Files.writeString(file,incompatible.toString());java.util.Map<String,String> overrides=new java.util.HashMap<>();manager.overrides(()->overrides);
 check(!manager.reload().has("error")&&!manager.hasAction("test.send"),"version mismatch disables declaration");JsonObject summary=manager.status().getAsJsonArray("plugins").get(0).getAsJsonObject();check(summary.get("mod_installed").getAsBoolean()&&summary.get("actual_version").getAsString().equals("1.20.1")&&!summary.get("version_match").getAsBoolean(),"real compatibility facts");
 overrides.put("test",summary.get("override_binding").getAsString());check(!manager.reload().has("error")&&manager.hasAction("test.send")&&manager.status().toString().contains("forced"),"local grant enables mismatch");
 Path brokenDir=Files.createDirectories(root.resolve("other"));Files.writeString(brokenDir.resolve("plugin.json"),"{broken");overrides.clear();check(manager.reload().has("error"),"unrelated malformed plugin retains snapshot");check(manager.create("test.send",new JsonObject()).tick().has("error"),"revoked grant denied even while snapshot retained");Files.delete(brokenDir.resolve("plugin.json"));Files.delete(brokenDir);check(!manager.reload().has("error")&&!manager.hasAction("test.send"),"repaired reload publishes revoked state");overrides.put("test",summary.get("override_binding").getAsString());manager.reload();
 incompatible.addProperty("target_version","changed");Files.writeString(file,incompatible.toString());check(!manager.reload().has("error")&&!manager.hasAction("test.send"),"editing manifest invalidates grant");
 overrides.clear();Files.writeString(file,manifest.toString());check(!manager.reload().has("error")&&manager.hasAction("test.send"),"old manifest still supported");
 System.out.println("PluginManagerTest passed "+checks);
 }
}
